```cypher
MATCH (bundle:SKU {sku_code: 'BDL-CA-0316'})
CALL {
    WITH bundle
    MATCH (bundle)-[e1:CONTAINS*1..6 (r, n | WHERE r.valid_from <= date('2026-10-01') AND (r.valid_to IS NULL OR date('2026-10-01') <= r.valid_to))]->(item:SKU)
    WHERE item.sku_code <> bundle.sku_code
    RETURN item, list_product(properties(rels(e1), 'qty')) AS bundle_to_item_qty
}
CALL {
    WITH item
    MATCH (item)-[e2:CONTAINS*1..1 (r, n | WHERE r.valid_from <= date('2026-10-01') AND (r.valid_to IS NULL OR date('2026-10-01') <= r.valid_to))]->(m:Model)
    RETURN m, list_product(properties(rels(e2), 'qty')) AS item_to_model_qty
}
CALL {
    WITH m
    MATCH (m)-[e3:CONTAINS*1..6 (r, n | WHERE r.valid_from <= date('2026-10-01') AND (r.valid_to IS NULL OR date('2026-10-01') <= r.valid_to))]->(c:Component {component_code: 'FOO-680-BLK-01235', is_assembly: false})
    RETURN list_product(properties(rels(e3), 'qty')) AS model_to_part_qty
}
RETURN sum(bundle_to_item_qty * item_to_model_qty * model_to_part_qty) AS total_part_qty
```

